package io.asv.odinlab;
import android.graphics.Bitmap;import org.opencv.android.Utils;import org.opencv.core.*;import org.opencv.imgproc.*;import java.util.*;
/** Lab-only classic contours, not the production detector or Tmikonen port. */
final class LabCv {
 static Bitmap reduced(Bitmap b,int cap){double scale=Math.min(1,cap/(double)Math.max(b.getWidth(),b.getHeight()));if(scale==1)return b;Mat src=new Mat(),dst=new Mat();try{Utils.bitmapToMat(b,src);Imgproc.resize(src,dst,new Size(Math.max(1,Math.rint(b.getWidth()*scale)),Math.max(1,Math.rint(b.getHeight()*scale))),0,0,Imgproc.INTER_AREA);Bitmap out=Bitmap.createBitmap(dst.cols(),dst.rows(),Bitmap.Config.ARGB_8888);Utils.matToBitmap(dst,out);return out;}finally{src.release();dst.release();}}
 static Bitmap clahe(Bitmap b){Mat rgba=new Mat(),rgb=new Mat(),lab=new Mat();List<Mat> channels=new ArrayList<>();CLAHE filter=Imgproc.createCLAHE(2,new Size(8,8));try{Utils.bitmapToMat(b,rgba);Imgproc.cvtColor(rgba,rgb,Imgproc.COLOR_RGBA2RGB);Imgproc.cvtColor(rgb,lab,Imgproc.COLOR_RGB2Lab);Core.split(lab,channels);filter.apply(channels.get(0),channels.get(0));Core.merge(channels,lab);Imgproc.cvtColor(lab,rgb,Imgproc.COLOR_Lab2RGB);Imgproc.cvtColor(rgb,rgba,Imgproc.COLOR_RGB2RGBA);Bitmap out=Bitmap.createBitmap(b.getWidth(),b.getHeight(),Bitmap.Config.ARGB_8888);Utils.matToBitmap(rgba,out);return out;}finally{for(Mat c:channels)c.release();rgba.release();rgb.release();lab.release();filter.collectGarbage();filter.clear();}}
 static List<float[]> detect(Bitmap source,boolean enhance){Bitmap b=reduced(source,960);int w=b.getWidth(),h=b.getHeight();Mat rgba=new Mat(),gray=new Mat(),edge=new Mat(),hierarchy=new Mat(),kernel=Imgproc.getStructuringElement(Imgproc.MORPH_RECT,new Size(3,3));List<MatOfPoint> contours=new ArrayList<>();CLAHE filter=null;
  try{Utils.bitmapToMat(b,rgba);Imgproc.cvtColor(rgba,gray,Imgproc.COLOR_RGBA2GRAY);if(enhance){filter=Imgproc.createCLAHE(2,new Size(8,8));filter.apply(gray,gray);}Imgproc.GaussianBlur(gray,gray,new Size(5,5),0);Imgproc.Canny(gray,edge,50,150);Imgproc.morphologyEx(edge,edge,Imgproc.MORPH_CLOSE,kernel);Imgproc.findContours(edge,contours,hierarchy,Imgproc.RETR_LIST,Imgproc.CHAIN_APPROX_SIMPLE);contours.sort((a,c)->Double.compare(Imgproc.contourArea(c),Imgproc.contourArea(a)));
   for(int n=0;n<Math.min(200,contours.size());n++){MatOfPoint c=contours.get(n);double area=Imgproc.contourArea(c)/(w*h);if(area<.02||area>.95)continue;MatOfPoint2f points=new MatOfPoint2f(c.toArray()),approx=new MatOfPoint2f();MatOfPoint polygon=null;try{Imgproc.approxPolyDP(points,approx,.02*Imgproc.arcLength(points,true),true);Point[] a=approx.toArray();if(a.length!=4)continue;polygon=new MatOfPoint(a);if(!Imgproc.isContourConvex(polygon))continue;float[] raw=new float[8];for(int i=0;i<4;i++){raw[i*2]=(float)(a[i].x/w);raw[i*2+1]=(float)(a[i].y/h);}try{double[][] q=UprightQuad.order(raw,w,h);if(CvQuadPolicy.accept(q,w,h))return Collections.singletonList(raw);}catch(IllegalArgumentException ignored){}}finally{points.release();approx.release();if(polygon!=null)polygon.release();}}
   return Collections.emptyList();
  }finally{for(Mat c:contours)c.release();rgba.release();gray.release();edge.release();hierarchy.release();kernel.release();if(filter!=null){filter.collectGarbage();filter.clear();}if(b!=source)b.recycle();}
 }
}
